-- APONTA P3 v2.17.0
-- SINCRONIZAÇÃO DAS ATIVIDADES E CÓDIGOS CONFORME PLANILHA REVISADA
-- Execute todo este arquivo no SQL Editor do Supabase.
-- Preserva apontamentos antigos: registros extras são inativados, não apagados.

begin;

create temp table tmp_aponta_activities_v217 (
  code text primary key,
  name text not null unique,
  discipline_code text not null,
  discipline_name text not null,
  sector_principal text not null,
  nature text not null,
  usage_description text not null,
  observation_requirement text not null,
  active boolean not null,
  primary_area text not null,
  secondary_area text
) on commit drop;


do $$
declare
  item record;
  v_activity_id uuid;
begin
  for item in select * from tmp_aponta_activities_v217 order by code loop
    v_activity_id := null;

    select a.id
      into v_activity_id
      from public.activities a
     where lower(trim(a.name)) = lower(trim(item.name))
        or regexp_replace(coalesce(a.code,''), '^EM-', '') = item.code
     order by
       case when lower(trim(a.name)) = lower(trim(item.name)) then 0 else 1 end,
       case when a.code = item.code then 0 else 1 end,
       a.created_at
     limit 1;

    if v_activity_id is null then
        name,activity_type,frequency,responsible_name,backup_name,
        code,discipline_code,discipline_name,sector_principal,nature,
        usage_description,observation_requirement,active
      ) values (
        item.name,'Demanda','','','',
        item.code,item.discipline_code,item.discipline_name,item.sector_principal,item.nature,
        item.usage_description,item.observation_requirement,item.active
      )
      returning id into v_activity_id;
    else
      update public.activities
         set code = null,
             active = false
       where code = item.code
         and id <> v_activity_id;

      update public.activities
         set name = item.name,
             code = item.code,
             discipline_code = item.discipline_code,
             discipline_name = item.discipline_name,
             sector_principal = item.sector_principal,
             nature = item.nature,
             usage_description = item.usage_description,
             observation_requirement = item.observation_requirement,
             active = item.active
       where id = v_activity_id;
    end if;

    delete from public.activity_area_links
     where activity_id = v_activity_id;

    values (v_activity_id,item.primary_area)
    on conflict do nothing;

    if item.secondary_area is not null and item.secondary_area <> item.primary_area then
      values (v_activity_id,item.secondary_area)
      on conflict do nothing;
    end if;
  end loop;
end $$;

update public.activities a
   set active = false
 where a.code like 'EM-%'
   and not exists (
     select 1
       from tmp_aponta_activities_v217 t
      where t.code = regexp_replace(a.code,'^EM-','')
   );

select
  count(*) filter (where a.active) as atividades_ativas,
  count(*) filter (where not a.active) as atividades_inativas,
  count(*) filter (where a.code like 'EM-%') as codigos_legados_restantes
from public.activities a;

commit;
